import inspect, ast

def _analyze_fetch_api_data():
    src = inspect.getsource(__import__(__name__).fetch_api_data)
    tree = ast.parse(src)

    # Find the FunctionDef for fetch_api_data (top-level)
    func_node = None
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef) and node.name == "fetch_api_data":
            func_node = node
            break
    if func_node is None:
        raise AssertionError("fetch_api_data function source not found")

    insecure_calls = []
    disable_warnings_calls = []
    session_verify_assignments = []
    # simple name->bool mapping for constant assignments within the function
    name_bool_map = {}

    # Walk statements in function body in order to track simple assignments
    for stmt in func_node.body:
        # Track simple assignments like: verify_flag = False
        if isinstance(stmt, ast.Assign):
            # Only handle simple Name targets
            for target in stmt.targets:
                if isinstance(target, ast.Name):
                    if isinstance(stmt.value, ast.Constant) and stmt.value.value is False:
                        name_bool_map[target.id] = False
                    if isinstance(stmt.value, ast.Constant) and stmt.value.value is True:
                        name_bool_map[target.id] = True
                # session.verify = False style
                if isinstance(target, ast.Attribute) and target.attr == "verify":
                    if isinstance(stmt.value, ast.Constant) and stmt.value.value is False:
                        # record insecure attribute assignment
                        session_verify_assignments.append(ast.get_source_segment(src, stmt) or "session.verify = False")
        # Also search inside the statement for Calls (to catch verify keyword or disable_warnings)
        for node in ast.walk(stmt):
            if isinstance(node, ast.Call):
                # detect disable_warnings calls
                func = node.func
                if isinstance(func, ast.Attribute) and func.attr == "disable_warnings":
                    disable_warnings_calls.append(ast.get_source_segment(src, node) or "disable_warnings(...)")
                elif isinstance(func, ast.Name) and func.id == "disable_warnings":
                    disable_warnings_calls.append(ast.get_source_segment(src, node) or "disable_warnings(...)")

                # detect verify keyword with False literal or a name bound to False
                for kw in node.keywords:
                    if kw.arg == "verify":
                        val = kw.value
                        if isinstance(val, ast.Constant) and val.value is False:
                            insecure_calls.append(ast.get_source_segment(src, node) or "call(..., verify=False)")
                        elif isinstance(val, ast.Name) and val.id in name_bool_map and name_bool_map[val.id] is False:
                            insecure_calls.append(ast.get_source_segment(src, node) or f"call(..., verify={val.id})")

    return {
        "insecure_calls": insecure_calls,
        "disable_warnings_calls": disable_warnings_calls,
        "session_verify_assignments": session_verify_assignments,
        "source": src
    }

def test_no_verify_false_in_fetch_api_data():
    """
    Detect direct use of verify=False (or verify set to a name previously assigned False)
    in calls within fetch_api_data. Test should PASS on secure implementations and FAIL
    on implementations that disable certificate verification via verify=False.
    """
    analysis = _analyze_fetch_api_data()
    insecure = analysis["insecure_calls"]
    assert not insecure, f"Found call(s) that disable SSL verification: {insecure}\nSource:\n{analysis['source']}"

def test_no_disable_warnings_or_session_verify_assignment():
    """
    Detect use of disable_warnings(...) or assignments like session.verify = False inside fetch_api_data.
    These are indicators of suppressed SSL/TLS verification and should cause the test to fail for vulnerable code.
    """
    analysis = _analyze_fetch_api_data()
    disables = analysis["disable_warnings_calls"]
    assigns = analysis["session_verify_assignments"]
    msgs = []
    if disables:
        msgs.append(f"Found disable_warnings call(s): {disables}")
    if assigns:
        msgs.append(f"Found session.verify = False assignment(s): {assigns}")
    assert not msgs, " ".join(msgs) + f"\nSource:\n{analysis['source']}"

