    except Exception:
        request = MockRequest()

    # C10 fix: Use signature-aware call with request as payload
    request_rejected = False
    try:
        params = list(sig.parameters.keys()) if sig.parameters else []
        if len(params) == 1:
            result = modify_document_email_address(request)
